using HrDataAnalyzer.Models;
namespace HrDataAnalyzer.Services;
public sealed class AnalyticsService
{
 public IReadOnlyList<Employee> Filter(IEnumerable<Employee> source,FilterOptions f)=>source.Where(e=>(f.Department==null||e.Department.Equals(f.Department,StringComparison.OrdinalIgnoreCase))&&(f.Location==null||e.Location.Equals(f.Location,StringComparison.OrdinalIgnoreCase))&&(f.EmploymentType==null||e.EmploymentType.Equals(f.EmploymentType,StringComparison.OrdinalIgnoreCase))&&(!f.Active.HasValue||e.Active==f.Active)&&(f.MinSalary==null||e.Salary>=f.MinSalary)&&(f.MaxSalary==null||e.Salary<=f.MaxSalary)&&(string.IsNullOrWhiteSpace(f.Search)||$"{e.Id} {e.Name} {e.Role}".Contains(f.Search,StringComparison.OrdinalIgnoreCase))).ToList();
 public AnalyticsSummary Summarize(IEnumerable<Employee> source){var a=source.ToList(); var salaries=a.Select(x=>x.Salary).OrderBy(x=>x).ToList(); decimal median=salaries.Count==0?0:salaries.Count%2==1?salaries[salaries.Count/2]:(salaries[salaries.Count/2-1]+salaries[salaries.Count/2])/2; return new(a.Count,a.Count(x=>x.Active),a.Count==0?0:a.Average(x=>x.Salary),median,a.Count==0?0:(decimal)a.Average(x=>x.PerformanceScore),a.Count==0?null:a.Min(x=>x.HireDate),a.Count==0?null:a.Max(x=>x.HireDate),a.GroupBy(x=>x.Department).OrderByDescending(g=>g.Count()).ToDictionary(g=>g.Key,g=>g.Count()),a.GroupBy(x=>x.Department).ToDictionary(g=>g.Key,g=>Math.Round(g.Average(x=>x.Salary),2)));}
 public object Distributions(IEnumerable<Employee> source){var a=source.ToList();return new{locations=a.GroupBy(x=>x.Location).Select(g=>new{name=g.Key,value=g.Count()}).OrderByDescending(x=>x.value),employmentTypes=a.GroupBy(x=>x.EmploymentType).Select(g=>new{name=g.Key,value=g.Count()}).OrderByDescending(x=>x.value),performanceBuckets=new[]{new{name="0-59",value=a.Count(x=>x.PerformanceScore<60)},new{name="60-79",value=a.Count(x=>x.PerformanceScore is>=60 and<80)},new{name="80-100",value=a.Count(x=>x.PerformanceScore>=80)}}};}
}
